#include <stdio.h>
#include <stdbool.h>

int main(void) {
        int ch;
        long lines = 0, words = 0, bytes = 0;
        long cur_len = 0, maxlen = 0;
        bool in_word = false;

        while ((ch = fgetc(stdin)) != EOF) {
                bytes++;
                if (ch == '\n') {
                        lines++;
                        if (cur_len > maxlen)
                                maxlen = cur_len;
                        cur_len = 0;
                        in_word = false;
                } else {
                        bool is_ws = (ch == ' ' || ch == '\t' || ch == '\v' ||
                                      ch == '\f' || ch == '\r');
                        if (!is_ws && !in_word) {
                                words++;
                                in_word = true;
                        } else if (is_ws) {
                                in_word = false;
                        }
                        cur_len++;
                }
        }

        if (cur_len > maxlen)
                maxlen = cur_len;

        printf("%ld %ld %ld %ld\n", lines, words, bytes, maxlen);
        return 0;
}
EOF
